VAR
  Overload_Trip_Delay : TON;
  Trip_Condition : BOOL;
END_VAR

// Define trip condition logic: 
// Trip if current > 47.7A (41.5A * 1.15 service factor) 
// Only trip if motor has been running for longer than 5 seconds to ignore inrush
Overload_Trip_Delay(IN := Motor_Running, PT := T#5S);

Trip_Condition := (Motor_Current > 47.7) AND Overload_Trip_Delay.Q;

IF Trip_Condition THEN
    Overload_Alarm := TRUE;
END_IF;

IF Fault_Reset THEN
    Overload_Alarm := FALSE;
END_IF;

IF Overload_Alarm THEN
    Motor_Stop := TRUE;
END_IF;

